"use client";

import { useEffect, useRef } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

interface ModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    children: React.ReactNode;
    width?: "sm" | "md" | "lg" | "xl";
}

export default function Modal({ isOpen, onClose, title, children, width = "md" }: ModalProps) {
    const modalRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose();
        };

        if (isOpen) {
            document.body.style.overflow = "hidden";
            window.addEventListener("keydown", handleEscape);
        }

        return () => {
            document.body.style.overflow = "unset";
            window.removeEventListener("keydown", handleEscape);
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const widthClasses = {
        sm: "max-w-md",
        md: "max-w-xl",
        lg: "max-w-3xl",
        xl: "max-w-5xl",
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 md:p-10 pointer-events-none">
            {/* Backdrop - More integrated fluid blur */}
            <div
                className="absolute inset-0 bg-on-surface/30 backdrop-blur-xl animate-in fade-in duration-700 pointer-events-auto"
                onClick={onClose}
            />

            {/* Modal Content - Refined Harmony container */}
            <div
                ref={modalRef}
                className={cn(
                    "relative w-full bg-surface dark:bg-background-dark rounded-[3.5rem] shadow-m3-4 overflow-hidden animate-in zoom-in-95 fade-in duration-500 border border-outline/5 pointer-events-auto",
                    widthClasses[width]
                )}
            >
                {/* Header - Subtle integrated divider */}
                <div className="px-12 py-10 border-b border-outline/5 flex items-center justify-between bg-surface-variant/5">
                    <div>
                        <h2 className="text-3xl font-black text-on-surface dark:text-white tracking-tighter leading-none">{title}</h2>
                        <p className="text-[11px] text-on-surface-variant/40 font-black uppercase tracking-[0.2em] mt-3">Refinamento Delta v2.0</p>
                    </div>
                    <button
                        onClick={onClose}
                        className="size-14 bg-surface-variant/20 hover:bg-surface-variant/40 text-on-surface-variant rounded-[1.5rem] transition-all flex items-center justify-center active:scale-90 shadow-sm"
                    >
                        <X size={24} />
                    </button>
                </div>

                {/* Body - Fluid custom scrollbar */}
                <div className="p-12 max-h-[80vh] overflow-y-auto custom-scrollbar">
                    {children}
                </div>
            </div>
        </div>
    );
}
